island (simple-autoware-safety-island).added:
# Illustrative ids, as `integrity` is: the HARA owns the real ones
# (play_launch phase 100 F3; rlm v0.3.13).
requirement: { id: SG-01, source: "island HARA (illustrative)" }
requirement: { id: SG-02, source: "island HARA (illustrative)" }
# What the level commands while it lasts (play_launch phase 100 F1;
# rlm v0.3.13): a velocity limit of zero to the HPC's planner.
commands:
  /planning/scenario_planning/max_velocity_candidates:
    - { field: max_velocity, equals: 0 }
# The minimal risk condition: a zero velocity command and no positive
# acceleration. Not the final deceleration: the operator ramps it at a
# jerk, so the first messages carry less (rlm safety-functions.md U2).
commands:
  /system/emergency/control_cmd:
    - { field: longitudinal.velocity, equals: 0 }
    - { field: longitudinal.acceleration, le: 0 }

rt_av_demo.added:
# Phase 102 E3/E4: what the level commands while it lasts. The brake
# controller sends one emergency command; the brake holds it, which the
# topic's `on_silence` states.
commands:
  /safety/brake_cmd:
    - { field: payload, equals: "emergency" }
requirement: { id: DEMO-1, source: "rt_av_demo, illustrative" }
# The brake actuator, outside the launch: it holds the last command, so
# a quiet command topic is not a released brake.
external: { side: sub, on_silence: { after: 200ms } }
